from pathlib import Path

path = Path('backend/static/admin.html')
text = path.read_text(encoding='utf-8')

MARKER = '/* ===== Compact Accordion Admin V3 ===== */'
if MARKER in text:
    raise SystemExit('accordion patch already applied')

login_b64 = ''''''

data_uri = 'data:image/jpeg;base64,' + login_b64
old = '<div class="auth-brand"><img src="/flapamamaku-icon.png" onerror="this.onerror=null;this.src=\'/favicon.ico\'" alt="App-Logo">'
new = f'<div class="auth-brand"><img src="{data_uri}" alt="Luzerner Fasnacht">'
text = text.replace(old, new)

css = r'''

    /* ===== Compact Accordion Admin V3 ===== */
    .admin-accordion { margin:10px 0; border:1px solid rgba(255,255,255,.09); border-radius:11px; background:#0a141b; overflow:hidden; }
    .admin-accordion > summary { list-style:none; cursor:pointer; display:flex; align-items:center; gap:10px; min-height:42px; padding:10px 13px; color:#f2d17f; font-size:13px; font-weight:900; background:#101c24; user-select:none; }
    .admin-accordion > summary::-webkit-details-marker { display:none; }
    .admin-accordion > summary::before { content:'›'; width:18px; font-size:20px; line-height:1; transition:transform .15s ease; }
    .admin-accordion[open] > summary::before { transform:rotate(90deg); }
    .admin-accordion-body { padding:12px 14px 14px; }
    .admin-accordion-body > :first-child { margin-top:0 !important; }
    .admin-accordion-body > :last-child { margin-bottom:0 !important; }
    #users-form .role-permission-grid,
    #members-form .role-permission-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
    #system .card.compact-collapsible { padding:0; overflow:hidden; }
    #system .card.compact-collapsible > .compact-card-head { cursor:pointer; padding:14px 16px; display:flex; align-items:center; justify-content:space-between; gap:12px; color:#f2d17f; font-weight:900; }
    #system .card.compact-collapsible > .compact-card-head::after { content:'Öffnen'; color:rgba(230,236,240,.48); font-size:11px; }
    #system .card.compact-collapsible.is-open > .compact-card-head::after { content:'Schliessen'; }
    #system .card.compact-collapsible > .compact-card-body { display:none; padding:0 16px 16px; }
    #system .card.compact-collapsible.is-open > .compact-card-body { display:block; }
    body:has(#auth-view:not(.hidden)) .auth-brand img,
    body:has(#password-change-view:not(.hidden)) .auth-brand img { width:126px; height:150px; object-fit:cover; border-radius:18px; padding:0; }
    @media (max-width:980px) {
      #users-form .role-permission-grid, #members-form .role-permission-grid { grid-template-columns:1fr; }
    }
'''
text = text.replace('</style>', css + '\n</style>', 1)

js = r'''
<script>
/* Compact accordion UI only; existing controls, IDs and handlers are preserved. */
(() => {
  function wrapElement(el, title, open=false) {
    if (!el || el.closest('.admin-accordion')) return;
    const details = document.createElement('details');
    details.className = 'admin-accordion';
    details.open = open;
    const summary = document.createElement('summary');
    summary.textContent = title;
    const body = document.createElement('div');
    body.className = 'admin-accordion-body';
    el.parentNode.insertBefore(details, el);
    details.append(summary, body);
    body.appendChild(el);
  }

  wrapElement(document.querySelector('#users-form .effective-rights-box'), 'Aktuell wirksame Rechte', false);
  wrapElement(document.querySelector('#users-form .role-permission-grid'), 'Rechte / Abweichungen von der Rolle', false);
  wrapElement(document.querySelector('#members-form #member-account-block'), 'Benutzerkonto & Berechtigungen', false);
  const memberFilters = document.querySelector('#member-filter-checkboxes')?.parentElement;
  wrapElement(memberFilters, 'Mitglieder-Filter', false);

  document.querySelectorAll('#system > .card, #system > .grid > .card, #system > .grid > div > .card').forEach((card, index) => {
    if (card.classList.contains('compact-collapsible') || card.id === 'setup-status-card' || card.id === 'onboarding-card') return;
    const heading = card.querySelector(':scope > h2, :scope > .preview-heading h2');
    if (!heading) return;
    const title = heading.textContent.trim();
    const head = document.createElement('div');
    head.className = 'compact-card-head';
    head.textContent = title;
    const body = document.createElement('div');
    body.className = 'compact-card-body';
    Array.from(card.childNodes).forEach(node => body.appendChild(node));
    card.append(head, body);
    card.classList.add('compact-collapsible');
    if (index === 0 || /branding|verein/i.test(title)) card.classList.add('is-open');
    head.addEventListener('click', () => card.classList.toggle('is-open'));
  });
})();
</script>
'''
text = text.replace('</body>', js + '\n</body>', 1)
path.write_text(text, encoding='utf-8')
